let fieldErrorOwner=null;
function fieldIssue(input){
  if(input===fullName)return creating&&fullName.value.trim().length<2?'invalidName':'';
  if(input===email)return !email.validity.valid||!/^\S+@[^\s@]+\.[^\s@]+$/.test(email.value.trim())?'invalidEmail':'';
  if(input===password)return !password.value?'invalidPassword':creating&&password.value.length<10?'short':'';
  if(input===confirmPassword)return creating&&confirmPassword.value!==password.value?'mismatch':'';
  return '';
}
function markField(input,key){
  if(key)input.setAttribute('aria-invalid','true');else input.removeAttribute('aria-invalid');
  input.closest('.inputbox').classList.toggle('invalid',!!key);
}
function fail(input,key,focus=true) {
  fieldErrorOwner=input;status(key,true);markField(input,key);if(focus)input.focus();
}
function validateBlur(input){
  if(busy||step||input.closest('[inert]'))return;
  const key=fieldIssue(input);
  if(key)fail(input,key,false);
  else {markField(input,'');if(fieldErrorOwner===input){fieldErrorOwner=null;status()}}
}

let resetErrorOwner=null;
function report(key,id,focus=true){
  resetNotice=key;resetError=true;resetErrorOwner=id||null;renderRecovery();
  if(id){byId(id).setAttribute('aria-invalid','true');if(focus)byId(id).focus();}
}
function recoveryIssue(id){
  const input=byId(id);
  if(id==='resetAddress')return step===1&&(!input.validity.valid||!/^\S+@[^\s@]+\.[^\s@]+$/.test(input.value.trim()))?'invalidEmail':'';
  if(id==='resetCode')return step===2&&!/^\d{6,10}$/.test(input.value.trim().replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-0x660)))?'expired':'';
  if(id==='resetNew')return step===3&&input.value.length<10?'short':'';
  if(id==='resetConfirm')return step===3&&input.value!==byId('resetNew').value?'mismatch':'';
  return '';
}
